func TestWpVersionCompareMatchesPHP(t *testing.T) {
	bad := 0
	for _, c := range phpVersionCases {
		if got := wpVersionCompare(c.a, c.b); got != c.want {
			t.Errorf("wpVersionCompare(%q, %q) = %d, PHP says %d", c.a, c.b, got, c.want)
			if bad++; bad > 20 {
				t.Fatal("too many mismatches")
			}
		}
	}
	t.Logf("%d pairs compared against PHP", len(phpVersionCases))
}
